"""Connect Four game logic: board state, moves, rendering, win detection."""

ROWS, COLS = 6, 7
EMPTY = "."


def new_board():
    """Return a fresh ROWS x COLS board filled with EMPTY cells."""
    return [[EMPTY for _ in range(COLS)] for _ in range(ROWS)]


def drop_disc(board, col, disc):
    """Drop disc into column col (0-indexed); return True on success."""
    for row in range(ROWS - 1, -1, -1):
        if board[row][col] == EMPTY:
            board[row][col] = disc
            return True
    return False


def is_full(board):
    """Return True when every column is filled (top row has no EMPTY)."""
    return all(board[0][c] != EMPTY for c in range(COLS))


def winning_line(board, disc):
    """Return the 4 cells forming a line for disc, or None if no win."""
    for r in range(ROWS):
        for c in range(COLS):
            for dr, dc in ((0, 1), (1, 0), (1, 1), (1, -1)):
                cells = []
                for i in range(4):
                    rr, cc = r + dr * i, c + dc * i
                    if 0 <= rr < ROWS and 0 <= cc < COLS and board[rr][cc] == disc:
                        cells.append((rr, cc))
                    else:
                        break
                if len(cells) == 4:
                    return cells
    return None


def render(board):
    """Return the board as a string with a numbered column header."""
    header = " ".join(str(c + 1) for c in range(COLS))
    rows = [" ".join(row) for row in board]
    return "\n".join([header] + rows)
